llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C49"],
      "claim": "Doravirine, a lipophilic heteroaromatic drug with a chlorophenyl and triazolone, had an absolute oral bioavailability of 64% in humans (100 mg tablet vs IV microdose), directly supporting F ≥20% for a similarly lipophilic heteroaromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Doravirine's oral bioavailability was not significantly affected by food, supporting the relevance of high F under the fed-state condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Brotizolam, a fused heteroaromatic benzodiazepine with a chlorophenyl, had absolute oral bioavailability of 70±22% in young healthy volunteers vs IV, supporting high F for a fused heteroaromatic chlorophenyl-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Alprazolam, a triazolobenzodiazepine with a chlorophenyl, had absolute oral bioavailability of 84% vs IV in humans, supporting high F for the query's heteroaromatic, lipophilic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Trazodone, a chlorophenyl piperazine triazolopyridinone, had absolute oral bioavailability of 63±4% in fasting healthy subjects vs IV, supporting high F despite substantial lipophilic/aromatic character.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence from human absolute oral bioavailability studies (doravirine 64%, brotizolam 70%, alprazolam 84%, trazodone 63%) supports F ≥20%; no affirmative evidence for F<20%. Physicochemical liabilities are outweighed by consistent high-F analogues, and food does not significantly reduce doravirine bioavailability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "Fed-state effect on the query is not directly measured; inferred from doravirine and general lipophilic drug behavior.",
    "High molecular weight and very high lipophilicity may pose solubility and metabolic liabilities not fully captured by the analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

